esbmc_test_source:
contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // We take amount as input and must fund this contract with amount before calling.
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        // require we have enough Ether to send
        require(address(this).balance >= amount);

        // observe before-values
        uint potBefore = c.pot(); if (__ESBMC_reverted()) return;
        uint balBefore = address(c).balance;

        // perform the call, recording whether it reverts
        bool reverted;
        c.play{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // observe after-values
        uint potAfter = c.pot(); if (__ESBMC_reverted()) return;
        uint balAfter = address(c).balance;

        // General rule: if call reverted, state unchanged; otherwise, when amount equals ticket price (10)
        // either pot increases by amount, or pot becomes zero and the contract's balance decreased by at least potBefore - 1.
        // We cannot reference constants inside C, so express fee as at most 1 by requiring that when pot resets to zero,
        // the contract's balance after is <= balBefore + amount - (potBefore - 1).

        assert(
            (reverted && potAfter == potBefore && balAfter == balBefore)
            ||
            (!reverted && (
                // If the call succeeded and amount is not the exact ticket, behavior of contract is not specified: we allow any change.
                // So we only enforce the strong invariant when amount == 10.
                (amount != 10)
                ||
                (
                    // If amount == 10, either pot increased by exactly amount
                    (potAfter == potBefore + amount)
                    // or pot was reset to zero and contract paid out nearly the full previous pot (at most 1 kept as fee)
                    ||
                    (
                        potAfter == 0
                        && (
                            // balAfter <= balBefore + amount - (potBefore - 1)
                            // rearranged to avoid negative underflow inside assert: compare sums
                            // balBefore + amount - (potBefore - 1) may underflow in uint, so rewrite as
                            // balAfter + (potBefore - 1) <= balBefore + amount
                            (balAfter + (potBefore == 0 ? 0 : potBefore - 1) <= balBefore + amount)
                        )
                    )
                )
            ))
        );
    }

    // allow receiving refunds from C during play()
    receive() external payable {}
}

