pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    EtherLotto c;

    function setUp() public {
        c = new EtherLotto();
    }

    function _run(uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        uint256 potBefore;
        try c.pot() returns (uint256 __r) { potBefore = __r; } catch { return; }
        uint balBefore = address(c).balance;
        bool reverted;
        try c.play{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 potAfter;
        try c.pot() returns (uint256 __r) { potAfter = __r; } catch { return; }
        uint balAfter = address(c).balance;
        assertTrue((reverted && potAfter == potBefore && balAfter == balBefore)
            ||
            (!reverted && (
                // If the call succeeded and amount is not the exact ticket, behavior of contract is not specified: we allow any change.
                // So we only enforce the strong invariant when amount == 10.
                (amount != 10)
                ||
                (
                    // If amount == 10, either pot increased by exactly amount
                    (potAfter == potBefore + amount)
                    // or pot was reset to zero and contract paid out nearly the full previous pot (at most 1 kept as fee)
                    ||
                    (
                        potAfter == 0
                        && (
                            // balAfter <= balBefore + amount - (potBefore - 1)
                            // rearranged to avoid negative underflow inside assert: compare sums
                            // balBefore + amount - (potBefore - 1) may underflow in uint, so rewrite as
                            // balAfter + (potBefore - 1) <= balBefore + amount
                            (balAfter + (potBefore == 0 ? 0 : potBefore - 1) <= balBefore + amount)
                        )
                    )
                )
            )));
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
